        assertEquals(0, sentMessages.all().size());
    }

    @Test
    void cancellingAConfirmedReservationNotifiesGovernanceAndFinance() {
        Reservation reservation = service.create(stay(102, "2027-03-10", "2027-03-11", 1, RatePlan.STANDARD));
        service.confirm(reservation.id());
        int messagesAfterConfirm = sentMessages.all().size();

        service.cancel(reservation.id());

        List<Message> messages = sentMessages.all();
        assertEquals(messagesAfterConfirm + 2, messages.size());
        assertEquals("governanca@pousadamarealta.com.br", messages.get(messagesAfterConfirm).to());
        assertTrue(messages.get(messagesAfterConfirm).subject().contains("Reserva cancelada"));
        assertEquals("financeiro@pousadamarealta.com.br", messages.get(messagesAfterConfirm + 1).to());
        assertTrue(messages.get(messagesAfterConfirm + 1).subject().contains("Reembolso"));
    }

    @Test
    void cancellingANonRefundableConfirmedReservationOnlyNotifiesGovernance() {
        Reservation reservation = service.create(stay(202, "2027-03-10", "2027-03-11", 1, RatePlan.NON_REFUNDABLE));
        service.confirm(reservation.id());
        int messagesAfterConfirm = sentMessages.all().size();

        service.cancel(reservation.id());

        List<Message> messages = sentMessages.all();
        assertEquals(messagesAfterConfirm + 1, messages.size());
        assertEquals("governanca@pousadamarealta.com.br", messages.get(messagesAfterConfirm).to());
        assertTrue(messages.get(messagesAfterConfirm).subject().contains("Reserva cancelada"));
    }
}

